import { type ReactElement } from "react";
import { getHintKeys, type HintKey } from "~/utils/keyboardHints";

type NodeSearchFooterProps = {
  canAct: boolean;
  canInsertLink: boolean;
  isActiveResultLinkable: boolean;
  onClose: () => void;
  onInsertLink: () => void;
  onOpenInNewTab: () => void;
  onOpenInSplit: () => void;
};

type FooterActionProps = {
  disabled?: boolean;
  keys: HintKey[];
  label: string;
  onClick: () => void;
};

const KeyHints = ({ keys }: { keys: HintKey[] }): ReactElement => (
  <>
    {getHintKeys(keys).map((symbol) => (
      <kbd className="dg-search-footer-key" key={symbol}>
        {symbol}
      </kbd>
    ))}
  </>
);

const FooterAction = ({
  disabled = false,
  keys,
  label,
  onClick,
}: FooterActionProps): ReactElement => (
  <button
    type="button"
    className="prompt-instruction dg-search-footer-action inline-flex h-auto cursor-pointer items-center gap-1 rounded-none border-0 p-0 disabled:cursor-not-allowed disabled:opacity-50"
    disabled={disabled}
    onClick={onClick}
    // Clicking must not move focus out of the query input, or the arrow keys stop
    // reaching the result list.
    onMouseDown={(event) => event.preventDefault()}
  >
    <KeyHints keys={keys} />
    <span className="ms-1">{label}</span>
  </button>
);

// Sits in Obsidian's `prompt-instructions` container for its type and spacing.
// Obsidian centres that row for the narrow quick switcher; this footer spans a
// full-width result list, so the actions start at its left edge instead.
export const NodeSearchFooter = ({
  canAct,
  canInsertLink,
  isActiveResultLinkable,
  onClose,
  onInsertLink,
  onOpenInNewTab,
  onOpenInSplit,
}: NodeSearchFooterProps): ReactElement => (
  <div className="prompt-instructions dg-search-footer shrink-0 justify-start px-0 pb-0 text-left">
    {/* Absent, not disabled: with no cursor there is nothing to insert into. */}
    {canInsertLink && (
      <FooterAction
        disabled={!canAct || !isActiveResultLinkable}
        keys={["Mod", "Enter"]}
        label="insert link at cursor"
        onClick={onInsertLink}
      />
    )}
    <FooterAction
      disabled={!canAct}
      keys={["Enter"]}
      label="open in new tab"
      onClick={onOpenInNewTab}
    />
    <FooterAction
      disabled={!canAct}
      keys={["Shift", "Enter"]}
      label="open in split"
      onClick={onOpenInSplit}
    />
    {/* The Escape key itself is handled by Obsidian's modal scope; this button
        is the pointer equivalent, so every footer item responds to a click. */}
    <FooterAction keys={["Escape"]} label="close" onClick={onClose} />
  </div>
);
import {
  App,
  Component,
  MarkdownRenderer,
  Modal,
  Notice,
  renderResults,
  TFile,
  type SearchResult,
} from "obsidian";
import {
  StrictMode,
  useEffect,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent,
  type MouseEvent,
  type ReactElement,
} from "react";
import { createRoot, Root } from "react-dom/client";
import type DiscourseGraphPlugin from "~/index";
import { NodeDisplayOptionsMenu } from "~/components/NodeDisplayOptionsMenu";
import { NodeSearchFooter } from "~/components/NodeSearchFooter";
import { NodeSortMenu } from "~/components/NodeSortMenu";
import { NodeTypeChipsSearchInput } from "~/components/NodeTypeChipsSearchInput";
import { NodeTypeFilterMenu } from "~/components/NodeTypeFilterMenu";
import type { SearchDropdownId } from "~/components/SearchDropdown";
import {
  openFileInNewLeaf,
  openFileInNewTab,
} from "~/components/canvas/utils/openFileUtils";
import {
  insertLinkAtInsertTarget,
  snapshotInsertTarget,
  type EditorInsertTarget,
} from "~/utils/editorInsertTarget";
import {
  QueryEngine,
  rankDiscourseNodesByTitle,
  type SearchableNode,
  type RankedDiscourseNode,
} from "~/services/QueryEngine";
import { getNodeTypeBadge, type NodeTypeBadge } from "~/utils/nodeTypeBadge";
import {
  buildAuthorNameByPath,
  resolveAuthorName,
  useAuthorNames,
} from "~/utils/discourseNodeAuthor";
import {
  DEFAULT_SORT_DIRECTION,
  DEFAULT_SORT_KEY,
  sortSearchResults,
  type SortDirection,
  type SortKey,
} from "~/utils/discourseNodeSort";
import { findTaggedLineElement } from "~/utils/taggedLineLocator";

const MAX_VISIBLE_RESULTS = 50;
const SEARCH_DEBOUNCE_MS = 250;

type NodesState =
  | { status: "loading" }
  | { status: "ready"; nodes: SearchableNode[] }
  | { status: "error"; message: string };

type NodeTypeDisplay = {
  name: string;
  badge: NodeTypeBadge;
};

type SearchResultRow = RankedDiscourseNode & {
  nodeType: NodeTypeDisplay;
};

const formatTimestamp = (epochMs: number): string =>
  new Date(epochMs).toLocaleString(undefined, {
    dateStyle: "medium",
    timeStyle: "short",
  });

const PREVIEW_FLASH_CLASS = "dg-search-preview-flash";

// An image reserves no height until it loads, which would shift a line scrolled to before then.
const waitForImages = async (container: HTMLElement): Promise<void> => {
  const pending = Array.from(container.querySelectorAll("img")).filter(
    (img) => !img.complete,
  );
  await Promise.race([
    Promise.all(
      pending.map(
        (img) =>
          new Promise<void>((resolve) => {
            img.addEventListener("load", () => resolve(), { once: true });
            img.addEventListener("error", () => resolve(), { once: true });
          }),
      ),
    ),
    new Promise<void>((resolve) => window.setTimeout(resolve, 1000)),
  ]);
};

const PreviewPane = ({
  app,
  result,
  authorName,
}: {
  app: App;
  result: SearchResultRow | undefined;
  authorName: string;
}): ReactElement => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  // Paired with its file so an in-flight read can't put one note's body under
  // another note's title.
  const [loaded, setLoaded] = useState<{ file: TFile; text: string } | null>(
    null,
  );
  const [renderedFile, setRenderedFile] = useState<TFile | null>(null);

  const file = result?.file;

  useEffect(() => {
    if (!file) {
      setLoaded(null);
      return;
    }
    let cancelled = false;
    void app.vault.cachedRead(file).then((text) => {
      if (!cancelled) setLoaded({ file, text });
    });
    return () => {
      cancelled = true;
    };
  }, [app, file]);

  useEffect(() => {
    const container = containerRef.current;
    if (!container || !file || loaded?.file !== file) return;

    container.empty();
    setRenderedFile(null);
    const component = new Component();
    let cancelled = false;
    void (async () => {
      await MarkdownRenderer.render(
        app,
        loaded.text.trim() || "This note is empty.",
        container,
        file.path,
        component,
      );
      await waitForImages(container);
      if (!cancelled) setRenderedFile(file);
    })();

    return () => {
      cancelled = true;
      component.unload();
      container.empty();
    };
  }, [app, file, loaded]);

  // Separate from rendering, so moving between two lines of one note only re-scrolls.
  const taggedLine = result?.tagLine?.line;
  useEffect(() => {
    const container = containerRef.current;
    // `loaded` still holds the previous note until the new file's read finishes.
    if (!container || !loaded || !file || renderedFile !== file) return;

    const target =
      taggedLine === undefined
        ? null
        : findTaggedLineElement({
            container,
            cache: app.metadataCache.getFileCache(file),
            text: loaded.text,
            line: taggedLine,
          });
    // Same-note switches don't re-render, so an unlocated line would keep the last scroll.
    if (!target) {
      container.scrollTop = 0;
      return;
    }
    target.scrollIntoView({ block: "center" });
    target.addClass(PREVIEW_FLASH_CLASS);
    const clearFlash = (): void => target.removeClass(PREVIEW_FLASH_CLASS);
    target.addEventListener("animationend", clearFlash, { once: true });
    return () => {
      target.removeEventListener("animationend", clearFlash);
      clearFlash();
    };
  }, [app, file, loaded, renderedFile, taggedLine]);

  if (!result || !file) {
    return (
      <div className="text-muted flex flex-1 items-center justify-center">
        Select a result to preview it.
      </div>
    );
  }

  return (
    <div className="flex flex-1 flex-col overflow-hidden">
      <div className="border-modifier-border border-b px-4 py-3">
        <div className="text-normal font-semibold">{result.title}</div>
        <div className="text-muted mt-1 text-xs">
          {`Created ${formatTimestamp(file.stat.ctime)} · Modified ${formatTimestamp(
            file.stat.mtime,
          )} · ${authorName}`}
        </div>
      </div>
      <div
        ref={containerRef}
        className="text-normal flex-1 overflow-y-auto px-4 py-3"
      />
    </div>
  );
};

const HighlightedTitle = ({
  title,
  match,
}: {
  title: string;
  match: SearchResult;
}): ReactElement => {
  const titleRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    const container = titleRef.current;
    if (!container) return;
    container.empty();
    renderResults(container, title, match);
    return () => container.empty();
  }, [title, match]);

  return (
    <div
      ref={titleRef}
      className="dg-search-result-title text-normal min-w-0 flex-1 truncate"
    />
  );
};

// Filled for a node, outlined for a candidate; both keep one box size.
const NodeTypePill = ({
  badge,
  isCandidate,
  label,
}: {
  badge: NodeTypeBadge;
  isCandidate: boolean;
  label: string;
}): ReactElement => (
  <span
    aria-label={isCandidate ? `${label} candidate` : label}
    style={{
      borderColor: badge.backgroundColor,
      backgroundColor: isCandidate ? "transparent" : badge.backgroundColor,
      ...(isCandidate ? {} : { color: badge.textColor }),
    }}
    className={`w-full rounded-full border border-solid py-px text-center text-xs font-semibold ${
      isCandidate ? "text-normal" : ""
    }`}
  >
    {badge.text}
  </span>
);

const ResultList = ({
  results,
  activeIndex,
  onActivate,
}: {
  results: SearchResultRow[];
  activeIndex: number;
  onActivate: (index: number) => void;
}): ReactElement => {
  const listRef = useRef<HTMLDivElement | null>(null);
  const pointerPositionRef = useRef<{ x: number; y: number } | null>(null);

  useEffect(() => {
    const active = listRef.current?.children[activeIndex];
    active?.scrollIntoView({ block: "nearest" });
  }, [activeIndex]);

  // Scrolling drags rows under a stationary cursor, and the mouseenter that
  // fires is not a choice. Compare coordinates rather than resetting a flag on
  // every activation, so hovering from row to row still counts as a choice.
  const hasPointerMoved = (event: MouseEvent<HTMLDivElement>): boolean => {
    const previous = pointerPositionRef.current;
    pointerPositionRef.current = { x: event.clientX, y: event.clientY };
    return (
      previous === null ||
      previous.x !== event.clientX ||
      previous.y !== event.clientY
    );
  };

  return (
    // No `aria-label` here: Obsidian renders one as a hover tooltip, which
    // covers the results the moment the pointer enters the list.
    <div
      ref={listRef}
      role="listbox"
      onMouseMove={(event) => {
        hasPointerMoved(event);
      }}
      className="flex-1 overflow-y-auto"
    >
      {results.map((result, index) => (
        <div
          key={`${result.file.path}:${result.tagLine?.line ?? ""}:${result.nodeTypeId}`}
          role="option"
          aria-selected={index === activeIndex}
          onMouseEnter={(event) => hasPointerMoved(event) && onActivate(index)}
          onClick={() => onActivate(index)}
          // Keeps focus in the search input, so the keyboard path stays live
          // after a click.
          onMouseDown={(event) => event.preventDefault()}
          className={`border-modifier-border flex cursor-pointer items-start gap-2 border-b px-3 py-2 ${
            index === activeIndex ? "bg-modifier-hover" : ""
          }`}
        >
          {/* Fixed-width column, so every title starts at the same x. */}
          <span className="flex w-11 shrink-0">
            <NodeTypePill
              badge={result.nodeType.badge}
              isCandidate={!!result.tagLine}
              label={result.nodeType.name}
            />
          </span>
          <div className="min-w-0 flex-1">
            <HighlightedTitle title={result.title} match={result.match} />
            {result.tagLine && (
              <div className="text-muted truncate text-xs">
                {`#${result.tagLine.tag} · ${result.file.basename} · L${result.tagLine.line + 1}`}
              </div>
            )}
          </div>
        </div>
      ))}
    </div>
  );
};

const NodeSearch = ({
  plugin,
  insertTarget,
  onClose,
}: {
  plugin: DiscourseGraphPlugin;
  insertTarget: EditorInsertTarget | null;
  onClose: () => void;
}): ReactElement => {
  const { app } = plugin;
  const [nodesState, setNodesState] = useState<NodesState>({
    status: "loading",
  });
  const [query, setQuery] = useState("");
  const [debouncedQuery, setDebouncedQuery] = useState("");
  const [activeIndex, setActiveIndex] = useState(0);
  // Single source of truth: ENG-2111's tag chips will read and write this too.
  const [selectedNodeTypeIds, setSelectedNodeTypeIds] = useState<string[]>([]);
  // One value per toolbar, so two panels can never be open at once.
  const [openDropdown, setOpenDropdown] = useState<SearchDropdownId>(null);
  const [sortKey, setSortKey] = useState<SortKey>(DEFAULT_SORT_KEY);
  const [showCandidates, setShowCandidates] = useState(false);
  const [tagCandidates, setTagCandidates] = useState<SearchableNode[]>([]);
  const [sortDirection, setSortDirection] = useState<SortDirection>(
    DEFAULT_SORT_DIRECTION,
  );
  // An editable span, so the query shares its line boxes with the filter chips.
  const inputRef = useRef<HTMLSpanElement | null>(null);
  const userNames = useAuthorNames({
    app,
    plugin,
    candidates: nodesState.status === "ready" ? nodesState.nodes : null,
  });

  const nodeTypesById = useMemo(() => {
    const byId = new Map<string, NodeTypeDisplay>();
    plugin.settings.nodeTypes.forEach((nodeType, nodeIndex) => {
      byId.set(nodeType.id, {
        name: nodeType.name,
        badge: getNodeTypeBadge({ nodeType, nodeIndex }),
      });
    });
    return byId;
  }, [plugin.settings.nodeTypes]);

  useEffect(() => {
    inputRef.current?.focus();
  }, []);

  // The fetch is synchronous today, so there is nothing to await or cancel yet.
  // Effects run after paint, so the loading state still renders for a frame; if
  // this ever becomes a network call, only this body changes.
  useEffect(() => {
    try {
      const nodes = new QueryEngine(app).getSearchableNodes(
        plugin.settings.nodeTypes,
      );
      setNodesState({ status: "ready", nodes });
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Unexpected error";
      new Notice(`Could not load discourse nodes: ${message}`);
      setNodesState({ status: "error", message });
    }
  }, [app, plugin.settings.nodeTypes]);

  // Rescans on every toggle-on, so node type edits made meanwhile are picked up.
  useEffect(() => {
    if (!showCandidates) {
      setTagCandidates([]);
      return;
    }
    let cancelled = false;
    const load = async (): Promise<void> => {
      try {
        const candidates = await new QueryEngine(app).getCandidateNodes(
          plugin.settings.nodeTypes,
        );
        if (!cancelled) setTagCandidates(candidates);
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        new Notice(`Could not load candidate nodes: ${message}`);
      }
    };
    void load();
    return () => {
      cancelled = true;
    };
  }, [app, plugin.settings.nodeTypes, showCandidates]);

  useEffect(() => {
    const timeout = window.setTimeout(
      () => setDebouncedQuery(query),
      SEARCH_DEBOUNCE_MS,
    );
    return () => window.clearTimeout(timeout);
  }, [query]);

  // Sort before truncating, so a date or alphabetical sort covers every match.
  const results = useMemo<SearchResultRow[]>(() => {
    if (nodesState.status !== "ready") return [];
    const ranked = rankDiscourseNodesByTitle({
      candidates: [...nodesState.nodes, ...tagCandidates],
      query: debouncedQuery,
      nodeTypeIds: selectedNodeTypeIds,
    });
    const authorNameByPath =
      sortKey === "author"
        ? buildAuthorNameByPath({
            app,
            files: ranked.map((result) => result.file),
            userNames,
          })
        : undefined;
    return sortSearchResults({
      results: ranked,
      sortKey,
      direction: sortDirection,
      authorNameByPath,
    })
      .slice(0, MAX_VISIBLE_RESULTS)
      .flatMap((result) => {
        // Loaders already drop unconfigured types; this covers a type deleted before they rerun.
        const nodeType = nodeTypesById.get(result.nodeTypeId);
        return nodeType ? [{ ...result, nodeType }] : [];
      });
  }, [
    app,
    nodesState,
    debouncedQuery,
    nodeTypesById,
    selectedNodeTypeIds,
    sortDirection,
    sortKey,
    tagCandidates,
    userNames,
  ]);

  // A narrowing query rebuilds `results` before the effect below can reset the
  // state, so the old index can point past the new list for one render. Clamping
  // here keeps the preview and the highlighted row from blanking for that frame.
  const activeIndexInRange = activeIndex < results.length ? activeIndex : 0;
  const activeResult = results[activeIndexInRange];

  // Only the preview shows an author, so resolve the selection, not all 50 rows.
  const authorName = useMemo(
    () =>
      activeResult
        ? resolveAuthorName({ app, file: activeResult.file, userNames })
        : "",
    [app, activeResult, userNames],
  );

  useEffect(() => {
    setActiveIndex(0);
  }, [results]);

  const moveActiveIndex = (delta: number) => {
    if (!results.length) return;
    setActiveIndex((current) => {
      const next = current + delta;
      if (next < 0) return 0;
      if (next > results.length - 1) return results.length - 1;
      return next;
    });
  };

  // Closes before opening: `close()` unmounts this React root, so the file and
  // app are read first and nothing touches state afterwards.
  const openActiveResult = (
    open: (app: App, file: TFile, options: { line?: number }) => Promise<void>,
  ): void => {
    if (!activeResult) return;
    const { file, tagLine } = activeResult;
    onClose();
    void open(app, file, { line: tagLine?.line }).catch((error: unknown) => {
      const message = error instanceof Error ? error.message : String(error);
      new Notice(`Could not open ${file.basename}: ${message}`);
    });
  };

  const handleDropdownOpenChange = ({
    id,
    isOpen,
  }: {
    id: NonNullable<SearchDropdownId>;
    isOpen: boolean;
  }): void => {
    setOpenDropdown(isOpen ? id : null);
    // Returns the keyboard path to the results the moment the panel closes.
    if (!isOpen) inputRef.current?.focus();
  };

  // A candidate is a line, not a node yet, so there is nothing to link to.
  const isActiveResultLinkable = !!activeResult && !activeResult.tagLine;

  // Closes before inserting, like `openActiveResult`.
  const insertLinkToActiveResult = (): void => {
    if (!activeResult || !insertTarget || !isActiveResultLinkable) return;
    const { file } = activeResult;
    onClose();
